M('orifice',P('假想自由出流孔面積 a=1e-5 m²；水頭 h=0.30 m；流量係數 Cd=0.6','Hypothetical freely discharging hole a=1e-5 m²; head h=0.30 m; discharge coefficient Cd=0.6'),'Q=Cd*a*sqrt(2*g*h)*86400','0.6*1e-5*math.sqrt(2*9.81*0.3)*86400','m³/d',P('只將 h 改成 0.60 m','Change only head h to 0.60 m'),'0.6*1e-5*math.sqrt(2*9.81*0.6)*86400',P('自由孔口流量隨孔面積線性、隨水頭平方根變化；膜下土層接觸可顯著改變實際洩漏。','Free-orifice flow scales linearly with hole area and with square-root head; contact with underlying soil can greatly alter actual leakage.'),P('只示範無背壓自由孔口，不能用來預測複合襯墊實際滲漏。','Only a free orifice without backpressure; not a prediction of leakage through a composite liner.'),P('在紙上比較相同孔面積的兩種水頭，另列膜土接觸、缺陷形狀與土層 K 等缺失條件。','Compare two heads for the same hole area on paper and list missing contact, geometry and underlying-soil conductivity conditions.'),P('忽略膜土緊密接觸或沿面流，會把簡化孔口式誤當成場址模型。','Ignoring membrane-soil contact or interface flow turns a simplified orifice equation into a false site model.'),P('複合襯墊每個孔洞的洩漏量都完全遵守無土層的自由孔口公式。','Every composite-liner hole leaks exactly as a free orifice without soil.'))
M('tensile',P('拉力 F=500 N；試條寬 w=0.025 m；厚度 t=0.002 m','Tensile force F=500 N; strip width w=0.025 m; thickness t=0.002 m'),'stress=F/(w*t)/1e6','500/(0.025*0.002)/1e6','MPa',P('只將 F 改成 600 N','Change only F to 600 N'),'600/(0.025*0.002)/1e6',P('名目拉應力由拉力除原始截面積；膜材與接縫失效還受剝離、蠕變及缺口影響。','Nominal tensile stress is force over original area; membrane and seam failure also depend on peel, creep and notches.'),P('均勻單軸名目應力，不是材料允許應力或接縫驗收標準。','Uniform uniaxial nominal stress, not allowable stress or a seam acceptance criterion.'),P('記錄試片尺寸、載入速率與破壞位置，區分母材、焊縫和夾具滑移。','Record specimen size, loading rate and failure location, distinguishing parent sheet, weld and grip slip.'),P('只報最大拉力而不報尺寸，無法公平比較不同試片。','Maximum force without specimen dimensions cannot compare samples fairly.'),P('拉斷力相同就表示不同寬度厚度的膜材強度完全相同。','Equal breaking force implies equal material strength for different strip dimensions.'))
M('pipe_velocity',P('圓管內徑 D=0.10 m；流量 Q=0.005 m³/s','Circular pipe internal diameter D=0.10 m; flow Q=0.005 m³/s'),'v=4*Q/(pi*D²)','4*0.005/(math.pi*0.1**2)','m/s',P('只將內徑 D 改成 0.08 m','Change only internal diameter D to 0.08 m'),'4*0.005/(math.pi*0.08**2)',P('滿管平均速度由流量除截面積；結垢縮小內徑可同時增加速度和阻力。','Full-pipe mean velocity is flow divided by area; scale reduces diameter and can increase both velocity and resistance.'),P('圓形滿管、無滑移平均值；未計部分充滿、泥砂和非牛頓特性。','Circular full pipe and mean velocity; partly full flow, sediment and non-Newtonian behaviour are excluded.'),P('核對真實內徑與流量，再觀察沖洗前後壓力、固體沉積和流量恢復。','Verify actual internal diameter and flow, then compare pressure, deposits and flow recovery before and after cleaning.'),P('使用外徑或名目尺寸代替有效內徑會低估速度。','Using outer or nominal diameter instead of effective inner diameter understates velocity.'),P('管壁結垢不影響管內流速或水力阻力。','Scale on pipe walls cannot affect velocity or hydraulic resistance.'))
M('density_volume',P('固體質量 m=6000 kg；假設堆積密度 rho=1500 kg/m³','Solid mass m=6000 kg; assumed bulk density rho=1500 kg/m³'),'V=m/rho','6000/1500','m³',P('只將 rho 改成 1200 kg/m³','Change only bulk density rho to 1200 kg/m³'),'6000/1200',P('材料體積依堆積密度而變；粒子密度不可直接代替含孔隙的堆積密度。','Material volume depends on bulk density; particle density cannot replace density including pores.'),P('已知乾濕基與均勻堆積，未包含後續壓密與膨脹。','Known moisture basis and uniform packing; later consolidation and swelling are omitted.'),P('用已知容積箱和秤重核對密度，將鬆填、壓實與乾濕狀態分欄。','Check density using a known-volume container and scale, separating loose, compacted, wet and dry conditions.'),P('把粒子密度當堆積密度會低估運輸或覆層需要體積。','Using particle density as bulk density underestimates hauling or cover volume.'),P('相同質量材料不論壓實狀態都占相同體積。','Equal material mass occupies the same volume regardless of compaction.'))

C('b486',P('由地基、膜土接觸、焊縫與排水證據理解複合襯墊','Understand composite liners through foundation, membrane contact, seams and drainage evidence'),'environment-waste',['landfill','landfaq','remedyguidance'],[
U(P('地形與地下水邊界','Terrain and groundwater boundary'),P('先將底部高程與地下水水頭分開，避免用地表坡向推定地下水流向。','Separate base elevation from groundwater head; surface slope does not determine subsurface flow direction.'),'gradient'),
U(P('低滲透土層原理','Low-permeability soil layer'),P('壓實土層提供水力阻抗，但其現場完整性與試體性能需各有證據。','Compacted soil supplies hydraulic resistance, but field continuity and specimen performance require separate evidence.'),'darcy'),
U(P('膜材缺陷與水頭效應','Membrane defects and head'),P('使用理想孔口比較水頭效應，再辨認複合襯墊中膜土接觸使模型失效的地方。','Compare head effects with an ideal orifice, then identify where membrane-soil contact invalidates that model.'),'orifice'),
U(P('焊縫試片與破壞位置','Seam specimens and failure location'),P('同時觀察拉伸和剝離相關證據，焊縫外觀整齊不能替代機械性能。','Inspect evidence relevant to both tensile and peel behaviour; neat seam appearance does not establish mechanical performance.'),'tensile'),
U(P('鋪設面積與品質覆蓋','Laying area and quality coverage'),P('把板片、接縫和穿越處編號，採樣圖需指出未檢區與特殊細部。','Identify panels, seams and penetrations; the inspection map must show untested regions and details.'),'sampling'),
U(P('排水坡向與局部窪地','Drainage grade and depressions'),P('襯墊上積水增加水頭；設計坡向需在鋪設後以實測高程核對。','Ponding above the liner increases head; verify installed grades by survey.'),'slope'),
U(P('收集槽容量與停泵','Sump capacity during pump outage'),P('重播假想停泵並追蹤水位，將暫存容量和膜上水頭連結。','Replay a hypothetical pump outage and relate storage to head above the membrane.'),'storage'),
U(P('集排水泵送需求','Collection-pump duty'),P('排水需求與處理場接收能力連結，泵送功率不能代替防滲性能證明。','Connect drainage duty to downstream treatment capacity; pumping power is not proof of liner integrity.'),'pump'),
U(P('降雨與上覆水量','Rainfall and overlying-water balance'),P('分開未覆蓋施工期與運轉期降雨情境，避免同一逕流假設套用全部階段。','Separate construction and operational rainfall scenarios rather than applying one runoff assumption throughout.'),'rain_balance'),
U(P('施工品質證據交接','Construction-quality evidence handoff'),P('將材料批號、焊縫試驗、修補位置與滲流監測串成可追溯紀錄。','Link material batches, seam tests, repair locations and seepage monitoring into traceable records.'),'uncertainty')])

C('b487',P('以水量、排水路徑和污染負荷設計滲出水收集的教學模型','Model leachate collection through water balance, drainage paths and pollutant loading'),'environment-waste',['landfill','landfaq','remedyguidance'],[
U(P('滲出水產生與水量邊界','Leachate generation and water boundary'),P('雨水、廢棄物初始含水與生物產水來源不同，先定義計算期間再估入流。','Rain, initial waste moisture and biological water differ; define the accounting period before estimating inflow.'),'rain_balance'),
U(P('集排水層坡向','Collection-layer grades'),P('排水層需導向集水點，局部反坡會增加水頭與積存。','The drainage layer must lead to sumps; reverse grades increase head and hold-up.'),'slope'),
U(P('穿孔管有效通流','Perforated-pipe conveyance'),P('管壁開孔收集與管內輸送是不同環節，平均管速不能證明所有開孔通暢。','Collection through openings differs from internal conveyance; mean pipe velocity does not prove clear perforations.'),'pipe_velocity'),
U(P('集水槽尖峰暫存','Peak sump storage'),P('將暴雨短時入流與泵送能力重播，找出最高液位而不只看日平均。','Replay storm-peak inflow against pumping capacity to identify maximum level rather than daily means.'),'storage'),
U(P('泵送揚程與輸送','Pumping head and transfer'),P('把集水深度、管損與末端高程列入總揚程，再核對實際泵點。','Include sump depth, line losses and discharge elevation in total head, then verify the pump operating point.'),'pump'),
U(P('堵塞與差壓診斷','Clogging and pressure diagnosis'),P('沉積、生物膜與結垢可能共同堵塞，壓差變化須連同流量判讀。','Sediment, biofilm and scaling can combine to block drainage; interpret pressure changes with flow.'),'pressure'),
U(P('有機與鹽分輸出負荷','Organic and salt export load'),P('高濃度小水量與低濃度大水量可能有相同負荷，後段處理需知道兩者。','A small concentrated flow and a large dilute flow can carry equal load; downstream treatment needs both quantities.'),'massflow'),
U(P('調勻池停留與混合','Equalization residence and mixing'),P('調勻可降低波動但不自動去除污染，沉積和死區需有額外觀察。','Equalization reduces variability but does not automatically remove pollutants; sediment and dead zones need separate observation.'),'retention'),
U(P('液位與流量感測校正','Level and flow calibration'),P('液位漂移可能掩蓋泵故障，需用獨立量測確認儀表零點與量程。','Level drift can conceal pump faults; independent measurement checks offset and range.'),'calibration'),
U(P('備援與長期維護','Backup and long-term maintenance'),P('模擬單泵失效並記錄備援切換、清洗和有效服務時間。','Simulate one-pump failure and document backup switching, cleaning and effective service time.'),'availability')])

C('b488',P('建立掩埋甲烷生成、收集、氧化與利用的分流收支','Balance generated landfill methane among collection, oxidation and utilization'),'environment-waste',['lfg','landfill','warmdocs'],[
U(P('有機物庫存與可分解部分','Organic inventory and degradable fraction'),P('掩埋垃圾的可分解部分隨組成而異，總噸數不能直接代表氣體潛力。','Degradable content varies with waste composition; total tonnage alone does not establish gas potential.'),'fraction'),
U(P('生成速率與時間演變','Generation rate over time'),P('以一階模型比較反應速度假設，明確保留多批次投入與含水差異未被解析。','Compare rate assumptions in a first-order model while noting unresolved multiple waste cohorts and moisture differences.'),'decay'),
U(P('收集與表面逸散','Collection and surface escape'),P('抽氣井回收的量只是生成量的一部分，覆土氧化與未收集逸散需分帳。','Well collection is only part of generation; account separately for cover oxidation and uncollected escape.'),'capture'),
U(P('抽氣壓差與空氣侵入','Extraction pressure and air intrusion'),P('過度負壓可能吸入空氣並改變氣質；讀值需和氧及甲烷組成一起看。','Excess suction can draw air and alter gas quality; interpret pressure with oxygen and methane composition.'),'pressure'),
U(P('集氣風機能量','Gas-collection blower energy'),P('管網阻力、冷凝液與井數影響風機需求，增加功率不保證增加有效甲烷回收。','Network resistance, condensate and well count affect blower duty; more power does not guarantee more effective methane recovery.'),'blower'),
U(P('氣體污染物負荷','Gas-contaminant loading'),P('氣體中的硫化物或其他雜質需按氣量和濃度估負荷，才能比較淨化需求。','Estimate impurity loading from gas volume and concentration before comparing conditioning requirements.'),'gas_mass'),
U(P('甲烷能量利用','Methane energy utilization'),P('以甲烷而非總掩埋氣計算化學能，並保留發電或直接用熱的不同邊界。','Calculate chemical energy from methane rather than total landfill gas and distinguish electricity from direct heat use.'),'gas_energy'),
U(P('淨能量與自用電','Net energy and internal electricity'),P('收集、淨化與發電輔機都應進入能量帳，避免只展示發電機毛輸出。','Include collection, conditioning and generator auxiliaries rather than showing gross generator output alone.'),'netpower'),
U(P('井網監測與資料缺口','Well-network monitoring gaps'),P('井況與氣體成分隨空間改變，失聯井不能以鄰井數值無標示取代。','Well condition and gas composition vary spatially; do not silently substitute neighboring values for missing wells.'),'coverage'),
U(P('停機情境與氣體去向','Outages and gas disposition'),P('在數位流程中比較利用設備停機時的替代處理邊界，記錄各通量而非假設氣體停止生成。','Compare alternative handling boundaries when utilization equipment is offline; log fluxes rather than assuming generation stops.'),'availability')])

C('b489',P('將防滲、排水、沉陷與植生整合為掩埋場最終覆蓋證據','Integrate infiltration control, drainage, settlement and vegetation into landfill-cover evidence'),'environment-waste',['landfill','remedy','warmdocs'],[
U(P('覆蓋層功能分工','Roles of cover layers'),P('將植生層、排水層與低滲透層分開，材料體積與壓實狀態要依各層記帳。','Separate vegetation, drainage and low-permeability layers, accounting for volume and compaction by layer.'),'density_volume'),
U(P('降雨、蒸散與滲漏','Rainfall, evapotranspiration and leakage'),P('蒸散型與低滲透型覆蓋的主導機制不同，水量比較需保留儲水項。','Evapotranspirative and low-permeability covers rely on different mechanisms; retain storage in water comparisons.'),'rain_balance'),
U(P('低滲透層完整性','Integrity of the low-permeability layer'),P('干濕循環和裂縫可能破壞連續性，試體低滲透性不能代替覆蓋後的監測。','Wetting-drying cycles and cracks can disrupt continuity; low specimen permeability does not replace post-installation monitoring.'),'darcy'),
U(P('表面排水坡度','Surface-drainage grade'),P('保持坡向與排水出口通暢，局部積水會增加入滲並影響植生。','Maintain grades and clear outlets; local ponding increases infiltration and affects vegetation.'),'slope'),
U(P('差異沉陷與裂縫','Differential settlement and cracking'),P('廢棄物壓縮與分解造成不均沉陷，覆蓋系統應以時間序列檢查局部梯度。','Waste compression and decomposition cause uneven settlement; inspect local gradients over time.'),'settlement'),
U(P('膜材與接縫受力','Membrane and seam loading'),P('沉陷和溫度作用會拉扯膜與接縫，試驗需辨識破壞位置而不只報最大力。','Settlement and temperature load membranes and seams; testing must identify failure location as well as peak force.'),'tensile'),
U(P('植生含水與季節','Vegetation moisture and seasonality'),P('表土太乾影響植生，過濕影響根系通氣；季節監測需記錄層位與含水基準。','Dry cover soil stresses plants while saturation restricts root aeration; retain layer and moisture basis in seasonal monitoring.'),'dry_solids'),
U(P('覆土甲烷氧化邊界','Cover methane-oxidation boundary'),P('氧化只能作用於到達含氧反應區的甲烷，不能用單一假定率抹去所有排放。','Oxidation acts only on methane reaching an oxygenated zone; one assumed rate cannot erase all emissions.'),'capture'),
U(P('巡查空間覆蓋','Inspection spatial coverage'),P('將裂縫、侵蝕、植生缺口和積水圖層疊合，規則網格之外仍需追蹤異常。','Overlay cracks, erosion, vegetation gaps and ponding, following anomalies beyond the regular inspection grid.'),'sampling'),
U(P('長期監測交接','Long-term monitoring handoff'),P('覆蓋完成不等於後續無需管理，保存維修與監測缺口以支援跨年度判讀。','Cover installation does not end management; retain repair and monitoring-gap histories for multi-year interpretation.'),'coverage')])

C('b490',P('追蹤污染物在粗土、細泥與洗液間的分配以評估土壤洗滌','Evaluate soil washing by following contamination among coarse soil, fines and wash water'),'environment-remediation',['remedy','remedyguidance','sw846'],[
U(P('場址分區與代表樣本','Site zones and representative samples'),P('先用歷史活動和粒徑區分土壤群，避免把不相容污染混成平均樣。','Group soils by history and size before sampling, avoiding composites that hide incompatible contaminants.'),'sampling'),
U(P('污染細粒與粒徑分級','Contaminated fines and size classification'),P('細粒高比表面常富集吸附污染物，洗滌可將它們集中而非化學消滅。','High-surface-area fines often concentrate sorbed contaminants; washing can concentrate rather than destroy them.'),'screen'),
U(P('乾基污染庫存','Dry-basis contaminant inventory'),P('進料污染總量需結合乾重和分析濃度，含水變化不能冒充去污。','Initial contaminant inventory requires dry mass and concentration; moisture changes cannot stand in for cleanup.'),'soil_inventory'),
U(P('粗細料污染收支','Coarse-fine contaminant balance'),P('將洗後粗料與細泥同時化驗，檢查污染物是否被集中到需要後續處理的物流。','Assay washed coarse soil and fines together to confirm transfer into a stream needing further treatment.'),'soil_balance'),
U(P('洗液負荷與水循環','Wash-water load and recycle'),P('循環水可累積溶解污染物，回用不代表污染負荷從系統消失。','Recycled water can accumulate dissolved contaminants; reuse does not remove their load from the system.'),'massflow'),
U(P('固液停留與分離','Solids-liquid residence and separation'),P('攪拌和分離的停留時間不同，需防止細泥隨粗料帶出。','Mixing and separation have different residence needs; prevent fines from leaving with coarse product.'),'retention'),
U(P('含水與產品重量','Moisture and product mass'),P('洗後土壤很濕，評估減量或回收時必須回到一致乾基。','Washed soil is wet; compare reduction or recovery on a common dry basis.'),'dry_solids'),
U(P('處理後浸出驗證','Post-treatment leaching verification'),P('總濃度降低與環境可移動性不同，適用性判斷需匹配使用情境和試驗。','Lower total concentration differs from mobility; match intended reuse with suitable tests.'),'leach'),
U(P('泵送與洗滌能耗','Pumping and washing energy'),P('額外用水與泵送可能抵銷部分處理優勢，應列出相同功能單位。','Additional water and pumping can offset some benefits; use the same functional unit for comparison.'),'pump'),
U(P('質量閉合與未知去向','Mass closure and unresolved pathways'),P('如果各出口污染總量無法閉合，先檢查含水、取樣與洗液，再討論反應。','If outlet inventories do not close, check moisture, sampling and wash water before claiming reaction.'),'uncertainty')])
